extern "C" uint32_t LumenInvokeA64LeafAbiForTest(
    uintptr_t entry_address,
    Lumen::Cpu::A64Dynarec::EntryContext* context,
    uint64_t* observations);

// Preserve the C++ caller, install sentinels in every AAPCS64 callee-saved
// integer register and in the preserved low halves of v8--v15, call the JIT
// entry, then snapshot its return boundary before restoring the caller.
__asm__(
    ".text\n"
    ".p2align 2\n"
    ".globl _LumenInvokeA64LeafAbiForTest\n"
    "_LumenInvokeA64LeafAbiForTest:\n"
    ".long 0xd503245f\n"
    "sub sp, sp, #192\n"
    "stp x19, x20, [sp, #0]\n"
    "stp x21, x22, [sp, #16]\n"
    "stp x23, x24, [sp, #32]\n"
    "stp x25, x26, [sp, #48]\n"
    "stp x27, x28, [sp, #64]\n"
    "stp x29, x30, [sp, #80]\n"
    "stp d8, d9, [sp, #96]\n"
    "stp d10, d11, [sp, #112]\n"
    "stp d12, d13, [sp, #128]\n"
    "stp d14, d15, [sp, #144]\n"
    "str x2, [sp, #160]\n"
    "mov x9, sp\n"
    "str x9, [sp, #168]\n"
    "mov x9, x0\n"
    "mov x0, x1\n"
    "mov x19, #0x119\n"
    "mov x20, #0x120\n"
    "mov x21, #0x121\n"
    "mov x22, #0x122\n"
    "mov x23, #0x123\n"
    "mov x24, #0x124\n"
    "mov x25, #0x125\n"
    "mov x26, #0x126\n"
    "mov x27, #0x127\n"
    "mov x28, #0x128\n"
    "mov x29, #0x129\n"
    "mov x10, #0xd08\n"
    "fmov d8, x10\n"
    "mov x10, #0xd09\n"
    "fmov d9, x10\n"
    "mov x10, #0xd10\n"
    "fmov d10, x10\n"
    "mov x10, #0xd11\n"
    "fmov d11, x10\n"
    "mov x10, #0xd12\n"
    "fmov d12, x10\n"
    "mov x10, #0xd13\n"
    "fmov d13, x10\n"
    "mov x10, #0xd14\n"
    "fmov d14, x10\n"
    "mov x10, #0xd15\n"
    "fmov d15, x10\n"
    "blr x9\n"
    "str w0, [sp, #176]\n"
    "ldr x9, [sp, #160]\n"
    "stp x19, x20, [x9, #0]\n"
    "stp x21, x22, [x9, #16]\n"
    "stp x23, x24, [x9, #32]\n"
    "stp x25, x26, [x9, #48]\n"
    "stp x27, x28, [x9, #64]\n"
    "str x29, [x9, #80]\n"
    "str d8, [x9, #88]\n"
    "str d9, [x9, #96]\n"
    "str d10, [x9, #104]\n"
    "str d11, [x9, #112]\n"
    "str d12, [x9, #120]\n"
    "str d13, [x9, #128]\n"
    "str d14, [x9, #136]\n"
    "str d15, [x9, #144]\n"
    "mov x10, sp\n"
    "str x10, [x9, #152]\n"
    "ldr x10, [sp, #168]\n"
    "str x10, [x9, #160]\n"
    "ldr w0, [sp, #176]\n"
    "ldp d14, d15, [sp, #144]\n"
    "ldp d12, d13, [sp, #128]\n"
    "ldp d10, d11, [sp, #112]\n"
    "ldp d8, d9, [sp, #96]\n"
    "ldp x29, x30, [sp, #80]\n"
    "ldp x27, x28, [sp, #64]\n"
    "ldp x25, x26, [sp, #48]\n"
    "ldp x23, x24, [sp, #32]\n"
    "ldp x21, x22, [sp, #16]\n"
    "ldp x19, x20, [sp, #0]\n"
    "add sp, sp, #192\n"
    "ret\n");
#endif

