template <size_t Size>
constexpr bool ContainsFastOpKind(const std::array<FastOpKind, Size>& kinds, FastOpKind kind)
{
	for (const FastOpKind candidate: kinds)
	{
		if (candidate == kind) return true;
	}
	return false;
}

template <size_t Size>
constexpr bool HasUniqueFastOpKinds(const std::array<FastOpKind, Size>& kinds)
{
	for (size_t first = 0; first < kinds.size(); first++)
	{
		for (size_t second = first + 1; second < kinds.size(); second++)
		{
			if (kinds[first] == kinds[second]) return false;
		}
	}
	return true;
}

constexpr bool HasCompleteDeadRflagsNormalizationManifest()
{
	for (size_t index = 0; index < DEAD_RFLAGS_NORMALIZATION_CASES.size();
	     index++)
	{
		const auto& entry = DEAD_RFLAGS_NORMALIZATION_CASES[index];
		if (static_cast<size_t>(entry.internal_kind) !=
		        DECODER_FAST_OP_KIND_COUNT + index ||
		    static_cast<size_t>(entry.decoder_kind) >=
		        DECODER_FAST_OP_KIND_COUNT ||
		    NormalizeDeadRflagsFastOpKind(entry.internal_kind) !=
		        entry.decoder_kind ||
		    NormalizeDeadRflagsFastOpKind(entry.decoder_kind) !=
		        entry.decoder_kind ||
		    !IsDeadRflagsElidedFastOpKind(entry.internal_kind) ||
		    IsDeadRflagsElidedFastOpKind(entry.decoder_kind))
		{
			return false;
		}
	}
	return true;
}

constexpr bool IsExpectedHostCallFastOpKind(FastOpKind kind)
{
	return kind == FastOpKind::Call ||
	       ContainsFastOpKind(TYPED_HELPER_FAST_OP_KINDS, kind);
}

bool IsPhase6BBLogic(FastOpKind kind)
{
	return kind == FastOpKind::OrReg16Mem || kind == FastOpKind::OrReg8Mem ||
	       kind == FastOpKind::AndReg8Mem || kind == FastOpKind::AndReg32Mem ||
	       kind == FastOpKind::AndReg64Mem || kind == FastOpKind::XorReg32Mem ||
	       kind == FastOpKind::XorReg64Mem || kind == FastOpKind::TestMem8Imm;
}

bool IsPhase6BBMultiply(FastOpKind kind)
{
	return kind == FastOpKind::ImulReg32Mem || kind == FastOpKind::ImulReg64Mem ||
	       kind == FastOpKind::ImulReg32MemImm || kind == FastOpKind::ImulReg64MemImm;
}

bool IsPhase6BBMemoryImmediate(FastOpKind kind)
{
	return kind == FastOpKind::CmpMem8Imm || kind == FastOpKind::CmpMem16Imm ||
	       kind == FastOpKind::CmpMem32Imm || kind == FastOpKind::CmpMem64Imm ||
	       kind == FastOpKind::TestMem8Imm ||
	       kind == FastOpKind::ImulReg32MemImm || kind == FastOpKind::ImulReg64MemImm;
}

bool IsPhase6BBCompareRegisterMemory(FastOpKind kind)
{
	return kind == FastOpKind::CmpReg32Mem || kind == FastOpKind::CmpReg64Mem;
}

bool IsPhase6BBCompareMemoryRegister(FastOpKind kind)
{
	return kind == FastOpKind::CmpMem32Reg || kind == FastOpKind::CmpMem64Reg;
}

bool IsPhase6BBCompareMemoryImmediate(FastOpKind kind)
{
	return kind == FastOpKind::CmpMem8Imm || kind == FastOpKind::CmpMem16Imm ||
	       kind == FastOpKind::CmpMem32Imm || kind == FastOpKind::CmpMem64Imm;
}

bool Phase6BBWritesDestination(FastOpKind kind)
{
	return !IsPhase6BBCompareRegisterMemory(kind) &&
	       !IsPhase6BBCompareMemoryRegister(kind) &&
	       !IsPhase6BBCompareMemoryImmediate(kind) &&
	       kind != FastOpKind::TestMem8Imm;
}

uint8_t Phase6BBWidth(FastOpKind kind)
{
	if (kind == FastOpKind::AndReg8Mem || kind == FastOpKind::OrReg8Mem ||
	    kind == FastOpKind::CmpMem8Imm || kind == FastOpKind::TestMem8Imm)
	{
		return 1;
	}
	if (kind == FastOpKind::OrReg16Mem || kind == FastOpKind::CmpMem16Imm)
		return 2;
	if (kind == FastOpKind::AndReg64Mem || kind == FastOpKind::XorReg64Mem ||
	    kind == FastOpKind::ImulReg64MemImm || kind == FastOpKind::ImulReg64Mem ||
	    kind == FastOpKind::AddReg64Mem || kind == FastOpKind::SubReg64Mem ||
	    kind == FastOpKind::CmpReg64Mem || kind == FastOpKind::CmpMem64Reg ||
	    kind == FastOpKind::CmpMem64Imm)
	{
		return 8;
	}
	return 4;
}

IrOpcode Phase6BBOpcode(FastOpKind kind)
{
	if (kind == FastOpKind::AddReg32Mem || kind == FastOpKind::AddReg64Mem)
		return IrOpcode::AddRegisterMemory;
	if (kind == FastOpKind::SubReg32Mem || kind == FastOpKind::SubReg64Mem)
		return IrOpcode::SubRegisterMemory;
	if (kind == FastOpKind::AndReg8Mem || kind == FastOpKind::AndReg32Mem ||
	    kind == FastOpKind::AndReg64Mem)
	{
		return IrOpcode::AndRegisterMemory;
	}
	if (kind == FastOpKind::OrReg8Mem || kind == FastOpKind::OrReg16Mem)
		return IrOpcode::OrRegisterMemory;
	if (kind == FastOpKind::XorReg32Mem || kind == FastOpKind::XorReg64Mem)
		return IrOpcode::XorRegisterMemory;
	if (IsPhase6BBCompareRegisterMemory(kind))
		return IrOpcode::CompareRegisterMemory;
	if (IsPhase6BBCompareMemoryRegister(kind))
		return IrOpcode::CompareMemoryRegister;
	if (IsPhase6BBCompareMemoryImmediate(kind))
		return IrOpcode::CompareMemoryImmediate;
	if (kind == FastOpKind::TestMem8Imm)
		return IrOpcode::TestMemoryImmediate;
	if (kind == FastOpKind::ImulReg32Mem || kind == FastOpKind::ImulReg64Mem)
		return IrOpcode::SignedMultiplyRegisterMemory;
	return IrOpcode::SignedMultiplyMemoryImmediate;
}

uint64_t Phase6BBNormalizedImmediate(FastOpKind kind, int32_t immediate)
{
	const uint8_t width = Phase6BBWidth(kind);
	if (width == 1) return static_cast<uint8_t>(immediate);
	if (width == 2) return static_cast<uint16_t>(immediate);
	if (width == 4) return static_cast<uint32_t>(immediate);
	return static_cast<uint64_t>(static_cast<int64_t>(immediate));
}

FastOp Phase6BBFastOp(FastOpKind kind, uint8_t destination,
	                  uint8_t source, uint8_t base, uint8_t index,
	                  uint8_t scale, int32_t displacement,
	                  uint64_t absolute, int32_t immediate, uint64_t rip)
{
	FastOp operation {};
	operation.kind         = kind;
	operation.base         = base;
	operation.index        = index;
	operation.scale        = scale;
	operation.displacement = displacement;
	operation.target       = absolute;
	operation.immediate    = immediate;
	operation.length       = IsPhase6BBMemoryImmediate(kind) ? 7 : 4;
	operation.rip          = rip;
	if (IsPhase6BBCompareMemoryRegister(kind))
	{
		operation.src = source;
	} else if (!IsPhase6BBCompareMemoryImmediate(kind) &&
	           kind != FastOpKind::TestMem8Imm)
	{
		operation.dst = destination;
	}
	return operation;
}

bool IsPhase6BCMemoryRegister(FastOpKind kind)
{
	return kind == FastOpKind::AddMem32Reg || kind == FastOpKind::AddMem64Reg ||
	       kind == FastOpKind::SubMem32Reg || kind == FastOpKind::SubMem64Reg ||
	       kind == FastOpKind::AndMem32Reg || kind == FastOpKind::AndMem64Reg;
}

bool IsPhase6BCLogic(FastOpKind kind)
{
	return kind == FastOpKind::AndMem32Reg || kind == FastOpKind::AndMem64Reg ||
	       kind == FastOpKind::AndMem8Imm;
}

bool IsPhase6BCIncrement(FastOpKind kind)
{
	return kind == FastOpKind::IncMem32 || kind == FastOpKind::IncMem64;
}

bool IsPhase6BCSetCondition(FastOpKind kind)
{
	return kind == FastOpKind::SetccMem8;
}

uint8_t Phase6BCWidth(FastOpKind kind)
{
	if (kind == FastOpKind::AndMem8Imm || kind == FastOpKind::SetccMem8) return 1;
	if (kind == FastOpKind::AddMem64Reg || kind == FastOpKind::SubMem64Reg ||
	    kind == FastOpKind::AndMem64Reg || kind == FastOpKind::IncMem64)
	{
		return 8;
	}
	return 4;
}

IrOpcode Phase6BCOpcode(FastOpKind kind)
{
	if (kind == FastOpKind::AddMem32Reg || kind == FastOpKind::AddMem64Reg)
		return IrOpcode::AddMemoryRegister;
	if (kind == FastOpKind::SubMem32Reg || kind == FastOpKind::SubMem64Reg)
		return IrOpcode::SubtractMemoryRegister;
	if (kind == FastOpKind::AndMem32Reg || kind == FastOpKind::AndMem64Reg)
		return IrOpcode::AndMemoryRegister;
	if (kind == FastOpKind::AndMem8Imm) return IrOpcode::AndMemoryImmediate;
	if (kind == FastOpKind::IncMem32 || kind == FastOpKind::IncMem64)
		return IrOpcode::IncrementMemory;
	return IrOpcode::SetConditionMemory;
}

FastOp Phase6BCFastOp(FastOpKind kind, uint8_t source,
	                  uint8_t base, uint8_t index, uint8_t scale,
	                  int32_t displacement, uint64_t absolute,
	                  int32_t immediate, uint8_t condition, uint64_t rip)
{
	FastOp operation {};
	operation.kind         = kind;
	operation.src          = source;
	operation.base         = base;
	operation.index        = index;
	operation.scale        = scale;
	operation.displacement = displacement;
	operation.target       = absolute;
	operation.immediate    = immediate;
	operation.condition    = condition;
	operation.length       = 4;
	operation.rip          = rip;
	return operation;
}

bool IsPhase6BDLoad(FastOpKind kind)
{
	return kind == FastOpKind::VmovssMem || kind == FastOpKind::VmovsdMem;
}

uint8_t Phase6BDWidth(FastOpKind kind)
{
	return kind == FastOpKind::VmovsdMem ||
	               kind == FastOpKind::VmovsdStoreMem
	           ? 8
	           : 4;
}

IrOpcode Phase6BDOpcode(FastOpKind kind)
{
	return IsPhase6BDLoad(kind) ? IrOpcode::VectorLoadScalar
	                           : IrOpcode::VectorStoreScalar;
}

FastOp Phase6BDFastOp(FastOpKind kind, uint8_t vector_register,
	                  uint8_t base, uint8_t index, uint8_t scale,
	                  int32_t displacement, uint64_t absolute, uint64_t rip)
{
	FastOp operation {};
	operation.kind         = kind;
	operation.dst          = vector_register;
	operation.base         = base;
	operation.index        = index;
	operation.scale        = scale;
	operation.displacement = displacement;
	operation.target       = absolute;
	operation.length       = 4;
	operation.rip          = rip;
	return operation;
}

uint8_t NarrowLoadWidth(FastOpKind kind)
{
	switch (kind)
	{
		case FastOpKind::MovReg8Mem: return 1;
		case FastOpKind::MovReg16Mem: return 2;
		default: return 0;
	}
}

FastOp NarrowLoadFastOp(FastOpKind kind, uint8_t destination, uint8_t base,
	                     uint8_t index, uint8_t scale, int32_t displacement,
	                     uint64_t absolute, uint64_t rip)
{
	FastOp operation {};
	operation.kind         = kind;
	operation.dst          = destination;
	operation.base         = base;
	operation.index        = index;
	operation.scale        = scale;
	operation.displacement = displacement;
	operation.target       = absolute;
	operation.length       = 4;
	operation.rip          = rip;
	return operation;
}

