std::array<FastOp, EXTENSION_FAST_OP_KINDS.size()> ExtensionFastOps()
{
	constexpr uint64_t rip = 0x100003b80ULL;
	std::array<FastOp, EXTENSION_FAST_OP_KINDS.size()> operations {};
	for (size_t index = 0; index < operations.size(); index++)
	{
		operations[index] = ExtensionFastOp(EXTENSION_FAST_OP_KINDS[index],
		                                         static_cast<uint8_t>(index),
		                                         static_cast<uint8_t>(index + 8),
		                                         rip + index * 4u);
	}
	return operations;
}

constexpr std::array<FastOpKind, 8> DIRECT_REGISTER_ADDRESS_FAST_OP_KINDS = {
	FastOpKind::MovReg8,
	FastOpKind::MovReg16,
	FastOpKind::MovImmReg8,
	FastOpKind::MovImmReg16,
	FastOpKind::LeaReg32,
	FastOpKind::LeaReg64,
	FastOpKind::BswapReg32,
	FastOpKind::BswapReg64,
};

uint8_t DirectRegisterAddressWidth(FastOpKind kind)
{
	switch (kind)
	{
		case FastOpKind::MovReg8:
		case FastOpKind::MovImmReg8: return 1;
		case FastOpKind::MovReg16:
		case FastOpKind::MovImmReg16: return 2;
		case FastOpKind::LeaReg32:
		case FastOpKind::BswapReg32: return 4;
		case FastOpKind::LeaReg64:
		case FastOpKind::BswapReg64: return 8;
		default: return 0;
	}
}

uint32_t ReferenceByteSwap32(uint32_t value)
{
	return ((value & 0x000000ffu) << 24u) | ((value & 0x0000ff00u) << 8u) |
	       ((value & 0x00ff0000u) >> 8u) | ((value & 0xff000000u) >> 24u);
}

uint64_t ReferenceByteSwap64(uint64_t value)
{
	return (static_cast<uint64_t>(ReferenceByteSwap32(static_cast<uint32_t>(value))) << 32u) |
	       ReferenceByteSwap32(static_cast<uint32_t>(value >> 32u));
}

uint64_t ReferenceEffectiveAddress(const FastOp& operation, const X64State& state)
{
	if (operation.base == IR_NO_REGISTER) return operation.target;
	uint64_t result = state.gpr[operation.base];
	if (operation.index != IR_NO_REGISTER) result += state.gpr[operation.index] << operation.scale;
	result += static_cast<uint64_t>(static_cast<int64_t>(operation.displacement));
	return result;
}

void ApplyDirectRegisterAddressOperation(const FastOp& operation, X64State* state)
{
	if (state == nullptr) return;
	const uint8_t width = DirectRegisterAddressWidth(operation.kind);
	const uint64_t mask = width == 1 ? 0xffULL : (width == 2 ? 0xffffULL : ~0ULL);
	auto write_register = [&](uint8_t destination, uint64_t value) {
		if (width == 4)
		{
			state->gpr[destination] = static_cast<uint32_t>(value);
		} else if (width == 8)
		{
			state->gpr[destination] = value;
		} else
		{
			state->gpr[destination] = (state->gpr[destination] & ~mask) | (value & mask);
		}
	};

	switch (operation.kind)
	{
		case FastOpKind::MovReg8:
		case FastOpKind::MovReg16:
		{
			const uint64_t source = state->gpr[operation.dst];
			write_register(operation.src, source);
			break;
		}
		case FastOpKind::MovImmReg8:
		case FastOpKind::MovImmReg16:
			write_register(operation.dst, static_cast<uint32_t>(operation.immediate));
			break;
		case FastOpKind::LeaReg32:
		case FastOpKind::LeaReg64:
		{
			const uint64_t address = ReferenceEffectiveAddress(operation, *state);
			write_register(operation.dst, address);
			break;
		}
		case FastOpKind::BswapReg32:
			write_register(operation.dst,
			               ReferenceByteSwap32(static_cast<uint32_t>(state->gpr[operation.dst])));
			break;
		case FastOpKind::BswapReg64:
			write_register(operation.dst, ReferenceByteSwap64(state->gpr[operation.dst]));
			break;
		default: break;
	}
	state->rip = operation.rip + operation.length;
}

std::array<FastOp, DIRECT_REGISTER_ADDRESS_FAST_OP_KINDS.size()> DirectRegisterAddressFastOps()
{
	constexpr uint64_t rip = 0x100003f00ULL;
	std::array<FastOp, DIRECT_REGISTER_ADDRESS_FAST_OP_KINDS.size()> operations {};
	for (size_t index = 0; index < operations.size(); index++)
	{
		operations[index].kind   = DIRECT_REGISTER_ADDRESS_FAST_OP_KINDS[index];
		operations[index].length = 4;
		operations[index].rip    = rip + index * 4u;
	}
	operations[0].dst = 8;
	operations[0].src = 9;
	operations[1].dst = 10;
	operations[1].src = 11;
	operations[2].dst = 12;
	operations[2].immediate = 0x1a5;
	operations[3].dst = 13;
	operations[3].immediate = 0x1beef;
	operations[4].dst          = 14;
	operations[4].base         = 14;
	operations[4].index        = 15;
	operations[4].scale        = 2;
	operations[4].displacement = 8;
	operations[5].dst          = 15;
	operations[5].base         = 8;
	operations[5].index        = 15;
	operations[5].scale        = 3;
	operations[5].displacement = -16;
	operations[6].dst = 8;
	operations[7].dst = 9;
	return operations;
}

struct DirectHelperProbe
{
	uint32_t calls = 0;
};

StepAction CountUnexpectedDirectHelper(void* opaque, EntryContext* context,
	                                   const Lumen::Cpu::A64Dynarec::IrInstruction*) noexcept
{
	auto* probe = static_cast<DirectHelperProbe*>(opaque);
	if (probe != nullptr) probe->calls++;
	if (context != nullptr) context->exit_reason = ExitReason::Bailout;
	return StepAction::Exit;
}

std::array<FastOp, 7> VectorFastOps()
{
	constexpr uint64_t rip = 0x100003c00ULL;
	std::array<FastOp, 7> operations {};
	operations[0].kind      = FastOpKind::VmovPackedMem;
	operations[0].dst       = 0;
	operations[0].base      = 7;
	operations[0].index     = 0xff;
	operations[0].immediate = 2;
	operations[0].condition = VECTOR_ZERO_UPPER | VECTOR_REQUIRE_ALIGNMENT;
	operations[0].length    = 4;
	operations[0].rip       = rip;
	operations[1].kind      = FastOpKind::VmovPackedReg;
	operations[1].dst       = 1;
	operations[1].base      = 0;
	operations[1].immediate = 2;
	operations[1].condition = VECTOR_ZERO_UPPER;
	operations[1].length    = 4;
	operations[1].rip       = rip + 4;
	operations[2].kind      = FastOpKind::VmovPackedReg;
	operations[2].dst       = 4;
	operations[2].base      = 0;
	operations[2].immediate = 2;
	operations[2].length    = 4;
	operations[2].rip       = rip + 8;
	operations[3].kind      = FastOpKind::VxorPackedReg;
	operations[3].dst       = 2;
	operations[3].src       = 0;
	operations[3].base      = 1;
	operations[3].immediate = 2;
	operations[3].condition = VECTOR_ZERO_UPPER;
	operations[3].length    = 4;
	operations[3].rip       = rip + 12;
	operations[4].kind      = FastOpKind::VxorPackedMem;
	operations[4].dst       = 3;
	operations[4].src       = 2;
	operations[4].base      = 5;
	operations[4].index     = 0xff;
	operations[4].immediate = 2;
	operations[4].condition = VECTOR_ZERO_UPPER;
	operations[4].length    = 4;
	operations[4].rip       = rip + 16;
	operations[5].kind      = FastOpKind::VmovPackedStoreMem;
	operations[5].dst       = 3;
	operations[5].base      = 6;
	operations[5].index     = 0xff;
	operations[5].immediate = 2;
	operations[5].condition = VECTOR_REQUIRE_ALIGNMENT;
	operations[5].length    = 4;
	operations[5].rip       = rip + 20;
	operations[6].kind      = FastOpKind::Jmp;
	operations[6].target    = 0;
	operations[6].length    = 2;
	operations[6].rip       = rip + 24;
	return operations;
}

