	EXPECT_TRUE(compiled.Execute(&native_context) == block.instruction_count);
	EXPECT_TRUE(native_context.exit_reason == ExitReason::Completed && native_context.direct_steps == 5);
	EXPECT_TRUE(native_context.executed_steps == reference_context.executed_steps &&
	            native_context.resume_rip == reference_context.resume_rip &&
	            native_context.exit_reason == reference_context.exit_reason);
