[[maybe_unused]] void TestPhase6CCDenseResidentArena()
{
#if defined(LUMEN_CPU_A64_DYNAREC_TEST)
	EXPECT_TRUE(IsDenseResidentCacheEnabled());
	if (!LUMEN_A64_TEST_HAS_MACOS_JIT_CALLBACK || !IsHostSupported()) return;

	auto make_verified = [](uint64_t rip)
	{
		FastOp operation {};
		operation.kind = FastOpKind::Nop;
		operation.length = 1;
		operation.rip = rip;
		return Lumen::Cpu::A64Dynarec::LowerFastOpsVerified(&operation, 1);
	};
	const auto baseline = GetDenseResidentArenaTestSnapshot();
	EXPECT_TRUE(baseline.executable_budget == 16u * 1024u * 1024u);
	EXPECT_TRUE(baseline.page_size != 0);
	ExecutableCodeMemory oversized;
	EXPECT_STATUS(
	    oversized.AllocateDenseResident(baseline.page_size),
	    Status::UnsupportedOperation);
	const void* first_address = nullptr;
	const void* second_address = nullptr;
	{
		auto first_ir = make_verified(UINT64_C(0x10001000));
		auto second_ir = make_verified(UINT64_C(0x10002000));
		EXPECT_STATUS(first_ir.status, Status::Ok);
		EXPECT_STATUS(second_ir.status, Status::Ok);
		EXPECT_TRUE(first_ir.block.has_value());
		EXPECT_TRUE(second_ir.block.has_value());
		if (!first_ir.block.has_value() || !second_ir.block.has_value()) return;
		DenseResidentBlock first;
		DenseResidentBlock second;
		EXPECT_STATUS(first.CompileVerified(
		                  *first_ir.block,
		                  EligibilityPolicy::ExistingOrProductionBasicBlock),
		              Status::Ok);
		EXPECT_STATUS(second.CompileVerified(
		                  *second_ir.block,
		                  EligibilityPolicy::ExistingOrProductionBasicBlock),
		              Status::Ok);
		first_address = first.CodeAddress();
		second_address = second.CodeAddress();
		EXPECT_TRUE(first_address != nullptr && second_address != nullptr &&
		            first_address != second_address);
		EXPECT_TRUE(first.CodeCapacity() < baseline.page_size &&
		            second.CodeCapacity() < baseline.page_size);
		EXPECT_TRUE(
		    reinterpret_cast<uintptr_t>(first_address) / baseline.page_size ==
		    reinterpret_cast<uintptr_t>(second_address) / baseline.page_size);

		auto execute = [](const DenseResidentBlock& artifact, uint64_t rip)
		{
			X64State state {};
			state.rip = rip;
			EntryContext context {};
			context.state = &state;
			context.cache_epoch = artifact.Epoch();
			context.resume_rip = rip;
			context.remaining_steps = 1;
			context.exit_reason = ExitReason::Bailout;
			const uint32_t steps = artifact.ExecutePreparedDirect(&context);
			return steps == 1 && context.executed_steps == 1 &&
			       context.direct_steps == 1 &&
			       context.exit_reason == ExitReason::Completed &&
			       context.resume_rip == rip + 1 && state.rip == rip + 1;
		};
		EXPECT_TRUE(execute(first, UINT64_C(0x10001000)));
		EXPECT_TRUE(execute(second, UINT64_C(0x10002000)));
		const auto live = GetDenseResidentArenaTestSnapshot();
		EXPECT_TRUE(live.live_slices == baseline.live_slices + 2);
		EXPECT_TRUE(live.mapped_bytes <= live.executable_budget);
		EXPECT_TRUE(live.page_count == baseline.page_count + 1);
	}
	const auto released = GetDenseResidentArenaTestSnapshot();
	EXPECT_TRUE(released.live_slices == baseline.live_slices);
	EXPECT_TRUE(released.releases >= baseline.releases + 2);
	EXPECT_TRUE(released.mapped_bytes <= released.executable_budget);
	{
		ExecutableCodeMemory reclassified;
		EXPECT_STATUS(reclassified.AllocateDenseResident(300), Status::Ok);
		EXPECT_TRUE(reclassified.Capacity() >= 304 &&
		            reclassified.Capacity() < baseline.page_size);
		const auto resized = GetDenseResidentArenaTestSnapshot();
		EXPECT_TRUE(resized.page_count == released.page_count);
		EXPECT_TRUE(resized.acquire_hits > released.acquire_hits);
	}

	{
		auto third_ir = make_verified(UINT64_C(0x10003000));
		EXPECT_STATUS(third_ir.status, Status::Ok);
		if (!third_ir.block.has_value()) return;
		DenseResidentBlock third;
		EXPECT_STATUS(third.CompileVerified(
		                  *third_ir.block,
		                  EligibilityPolicy::ExistingOrProductionBasicBlock),
		              Status::Ok);
		EXPECT_TRUE(third.CodeAddress() == first_address ||
		            third.CodeAddress() == second_address);
		const auto reused = GetDenseResidentArenaTestSnapshot();
		EXPECT_TRUE(reused.page_count == released.page_count);
		EXPECT_TRUE(reused.acquire_hits > released.acquire_hits);
		EXPECT_TRUE(reused.mapped_bytes <= reused.executable_budget);
	}

	// Fill the executable budget with one-slice pages, prove N+1 fails closed,
	// then release exactly one slice and recover without mapping beyond 16 MiB.
	const size_t page_capacity = baseline.executable_budget / baseline.page_size;
	std::vector<std::unique_ptr<ExecutableCodeMemory>> budget_leases;
	budget_leases.reserve(page_capacity);
	bool capacity_observed = false;
	for (size_t index = 0; index <= page_capacity; index++)
	{
		auto lease = std::make_unique<ExecutableCodeMemory>();
		const Status status =
		    lease->AllocateDenseResident(baseline.page_size - 4u);
		if (status == Status::CapacityExceeded)
		{
			capacity_observed = true;
			break;
		}
		EXPECT_STATUS(status, Status::Ok);
		if (status != Status::Ok) break;
		budget_leases.push_back(std::move(lease));
	}
	const auto full = GetDenseResidentArenaTestSnapshot();
	EXPECT_TRUE(capacity_observed && !budget_leases.empty());
	EXPECT_TRUE(full.mapped_bytes == full.executable_budget);
	budget_leases.back().reset();
	ExecutableCodeMemory recovered;
	EXPECT_STATUS(
	    recovered.AllocateDenseResident(baseline.page_size - 4u), Status::Ok);
	const auto recovered_snapshot = GetDenseResidentArenaTestSnapshot();
	EXPECT_TRUE(recovered_snapshot.mapped_bytes ==
	            recovered_snapshot.executable_budget);

	// Phase-6CF must retain the already emitted staging buffer across a full
	// arena. The callback releases one slice and the compiler retries only
	// Allocate+Publish, returning the exact requested class to its caller.
	auto callback_ir = make_verified(UINT64_C(0x10004000));
	EXPECT_STATUS(callback_ir.status, Status::Ok);
	EXPECT_TRUE(callback_ir.block.has_value());
	if (callback_ir.block.has_value())
	{
		struct ReclaimContext
		{
			ExecutableCodeMemory* lease;
			size_t calls = 0;
			size_t required_capacity = 0;
		};
		ReclaimContext reclaim_context {&recovered};
		auto reclaimer = [](void* opaque, size_t required_capacity)
		{
			auto* context = static_cast<ReclaimContext*>(opaque);
			if (context == nullptr || context->lease == nullptr ||
			    context->lease->Capacity() == 0)
			{
				return false;
			}
			context->calls++;
			context->required_capacity = required_capacity;
			context->lease->Reset();
			return true;
		};
		DenseResidentBlock callback_compiled;
		EXPECT_STATUS(
		    callback_compiled.CompileVerified(
		        *callback_ir.block,
		        EligibilityPolicy::ExistingOrProductionBasicBlock, false,
		        reclaimer, &reclaim_context),
		    Status::Ok);
		EXPECT_TRUE(reclaim_context.calls == 1 &&
		            reclaim_context.required_capacity != 0 &&
		            reclaim_context.required_capacity ==
		                callback_compiled.CodeCapacity() &&
		            recovered.Capacity() == 0 &&
		            callback_compiled.IsCompiled());
		const auto callback_snapshot = GetDenseResidentArenaTestSnapshot();
		EXPECT_TRUE(callback_snapshot.mapped_bytes ==
		            callback_snapshot.executable_budget);
	}
#endif
}

[[maybe_unused]] void TestJitPageRecycleLifecycle()
{
#if defined(LUMEN_CPU_A64_DYNAREC_TEST)
	EXPECT_TRUE(IsJitPageRecycleEnabled());
	EXPECT_TRUE(IsJitPageRecycleEnabled());
	if (!LUMEN_A64_TEST_HAS_MACOS_JIT_CALLBACK || !IsHostSupported()) return;

	auto make_code = [](uint64_t value, A64CodeBuffer* buffer)
	{
		return buffer->EmitReturnConstant(value);
	};

	// The same physical page may be leased again only after the old artifact
	// is empty. The new artifact must have a distinct epoch and native result.
	ResetJitPageRecyclePoolForTest();
	constexpr uint64_t first_value = 0x1111222233334444ULL;
	constexpr uint64_t second_value = 0xaaaabbbbccccddddULL;
	std::array<uint8_t, 32> first_staging {};
	A64CodeBuffer first_buffer(first_staging.data(), first_staging.size());
	EXPECT_STATUS(make_code(first_value, &first_buffer), Status::Ok);
	EXPECT_STATUS(first_buffer.EmitReturn(), Status::Ok);
	ExecutableCodeMemory first;
	EXPECT_STATUS(first.Allocate(first_buffer.SizeBytes()), Status::Ok);
	EXPECT_STATUS(first.Publish(first_buffer.Data(), first_buffer.SizeBytes()),
	              Status::Ok);
	const void* first_address = first.EntryAddress();
	const uint64_t first_epoch = first.Epoch();
	const SmokeEntry first_entry = GetSmokeEntry(first);
	EXPECT_TRUE(first_entry != nullptr);
	if (first_entry != nullptr) EXPECT_TRUE(first_entry() == first_value);
	first.RetireForReuseAfterQuiescenceForTest();
	EXPECT_TRUE(first.EntryAddress() == nullptr);
	EXPECT_TRUE(first.Capacity() == 0);
	EXPECT_TRUE(first.PublishedSize() == 0);
	EXPECT_TRUE(first.Epoch() != first_epoch);
	auto snapshot = GetJitPageRecycleTestSnapshot();
	EXPECT_TRUE(snapshot.slot_capacity == 64);
	EXPECT_TRUE(snapshot.page_size != 0);
	EXPECT_TRUE(snapshot.resident == 1);
	EXPECT_TRUE(snapshot.retire_attempts == 1);
	EXPECT_TRUE(snapshot.retire_stored == 1);

	std::array<uint8_t, 24> second_staging {};
	A64CodeBuffer second_buffer(second_staging.data(), second_staging.size());
	EXPECT_STATUS(make_code(second_value, &second_buffer), Status::Ok);
	ExecutableCodeMemory second;
	EXPECT_STATUS(second.Allocate(second_buffer.SizeBytes()), Status::Ok);
	const uint64_t second_epoch = second.Epoch();
	EXPECT_TRUE(second_epoch != first_epoch);
	EXPECT_STATUS(second.Publish(second_buffer.Data(), second_buffer.SizeBytes()),
	              Status::Ok);
	EXPECT_TRUE(second.EntryAddress() == first_address);
	uint32_t recycled_tail = UINT32_MAX;
	std::memcpy(&recycled_tail,
	            static_cast<const uint8_t*>(second.EntryAddress()) +
	                second.PublishedSize(),
	            sizeof(recycled_tail));
	EXPECT_TRUE(recycled_tail == 0);
	const SmokeEntry second_entry = GetSmokeEntry(second);
	EXPECT_TRUE(second_entry != nullptr);
	if (second_entry != nullptr) EXPECT_TRUE(second_entry() == second_value);
	snapshot = GetJitPageRecycleTestSnapshot();
	EXPECT_TRUE(snapshot.resident == 0);
	EXPECT_TRUE(snapshot.acquire_hits == 1);
	second.Reset();
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 0);

	// A stale dispatch context must not authorize the next owner merely because
	// the executable base was recycled. The new epoch rejects the old context
	// before native entry, while its own epoch executes the replacement block.
	ResetJitPageRecyclePoolForTest();
	FastOp epoch_operation {};
	epoch_operation.kind = FastOpKind::Nop;
	epoch_operation.length = 1;
	epoch_operation.rip = UINT64_C(0x10000f000);
	IrBlock epoch_block {};
	EXPECT_STATUS(LowerFastOps(&epoch_operation, 1, &epoch_block), Status::Ok);
	{
		CompiledBlock first_compiled;
		EXPECT_STATUS(first_compiled.Compile(
		                  epoch_block,
		                  EligibilityPolicy::ExistingOrDirectFallthrough),
		              Status::Ok);
		const void* compiled_address = first_compiled.CodeAddress();
		const uint64_t first_compiled_epoch = first_compiled.Epoch();
		first_compiled.RetireCodeForReuseAfterQuiescence();
		EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 1);

		CompiledBlock second_compiled;
		EXPECT_STATUS(second_compiled.Compile(
		                  epoch_block,
		                  EligibilityPolicy::ExistingOrDirectFallthrough),
		              Status::Ok);
		EXPECT_TRUE(second_compiled.CodeAddress() == compiled_address);
		EXPECT_TRUE(second_compiled.Epoch() != first_compiled_epoch);

		X64State stale_state {};
		stale_state.rip = epoch_block.rip;
		EntryContext stale_context {
		    &stale_state, nullptr, first_compiled_epoch, epoch_block.rip,
		    epoch_block.instruction_count, 99, ExitReason::Completed, 99};
		EXPECT_TRUE(second_compiled.Execute(&stale_context) == 0);
		EXPECT_TRUE(stale_context.executed_steps == 0 &&
		            stale_context.direct_steps == 0 &&
		            stale_context.resume_rip == epoch_block.rip &&
		            stale_context.exit_reason == ExitReason::Invalidated);
		EXPECT_TRUE(stale_state.rip == epoch_block.rip);

		X64State current_state {};
		current_state.rip = epoch_block.rip;
		EntryContext current_context {
		    &current_state, nullptr, second_compiled.Epoch(), epoch_block.rip,
		    epoch_block.instruction_count, 99, ExitReason::Bailout, 99};
		EXPECT_TRUE(second_compiled.Execute(&current_context) ==
		            epoch_block.instruction_count);
		EXPECT_TRUE(current_context.executed_steps ==
		                epoch_block.instruction_count &&
		            current_context.direct_steps ==
		                epoch_block.instruction_count &&
		            current_context.resume_rip == epoch_block.fallthrough_rip &&
		            current_context.exit_reason == ExitReason::Completed);
		EXPECT_TRUE(current_state.rip == epoch_block.fallthrough_rip);
	}

	// Only one-page, successfully published artifacts are eligible. An
	// unpublished page acquired from the pool is unmapped, never reinserted.
	ResetJitPageRecyclePoolForTest();
	ExecutableCodeMemory donor;
	EXPECT_STATUS(donor.Allocate(first_buffer.SizeBytes()), Status::Ok);
	EXPECT_STATUS(donor.Publish(first_buffer.Data(), first_buffer.SizeBytes()),
	              Status::Ok);
	donor.RetireForReuseAfterQuiescenceForTest();
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 1);
	ExecutableCodeMemory unpublished;
	EXPECT_STATUS(unpublished.Allocate(first_buffer.SizeBytes()), Status::Ok);
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 0);
	unpublished.RetireForReuseAfterQuiescenceForTest();
	EXPECT_TRUE(unpublished.EntryAddress() == nullptr);
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 0);

	ResetJitPageRecyclePoolForTest();
	snapshot = GetJitPageRecycleTestSnapshot();
	ExecutableCodeMemory multipage;
	EXPECT_STATUS(multipage.Allocate(snapshot.page_size + 1), Status::Ok);
	EXPECT_TRUE(multipage.Capacity() > snapshot.page_size);
	EXPECT_STATUS(multipage.Publish(first_buffer.Data(), first_buffer.SizeBytes()),
	              Status::Ok);
	multipage.RetireForReuseAfterQuiescenceForTest();
	EXPECT_TRUE(multipage.EntryAddress() == nullptr);
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 0);

	// A full 64-page stack remains bounded. The 65th retirement is unmapped;
	// all 64 subsequent leases are unique and consume the pool exactly once.
	ResetJitPageRecyclePoolForTest();
	const size_t slot_capacity = GetJitPageRecycleTestSnapshot().slot_capacity;
	std::vector<std::unique_ptr<ExecutableCodeMemory>> retired;
	retired.reserve(slot_capacity + 1);
	for (size_t index = 0; index <= slot_capacity; index++)
	{
		auto memory = std::make_unique<ExecutableCodeMemory>();
		EXPECT_STATUS(memory->Allocate(first_buffer.SizeBytes()), Status::Ok);
		EXPECT_STATUS(memory->Publish(first_buffer.Data(), first_buffer.SizeBytes()),
		              Status::Ok);
		retired.emplace_back(std::move(memory));
	}
	for (auto& memory: retired)
		memory->RetireForReuseAfterQuiescenceForTest();
	snapshot = GetJitPageRecycleTestSnapshot();
	EXPECT_TRUE(snapshot.resident == slot_capacity);
	EXPECT_TRUE(snapshot.retire_attempts == slot_capacity + 1);
	EXPECT_TRUE(snapshot.retire_stored == slot_capacity);
	EXPECT_TRUE(snapshot.retire_overflows == 1);

	std::vector<std::unique_ptr<ExecutableCodeMemory>> leased;
	std::vector<const void*> leased_addresses;
	leased.reserve(slot_capacity);
	leased_addresses.reserve(slot_capacity);
	for (size_t index = 0; index < slot_capacity; index++)
	{
		auto memory = std::make_unique<ExecutableCodeMemory>();
		EXPECT_STATUS(memory->Allocate(second_buffer.SizeBytes()), Status::Ok);
		EXPECT_STATUS(memory->Publish(second_buffer.Data(), second_buffer.SizeBytes()),
		              Status::Ok);
		leased_addresses.push_back(memory->EntryAddress());
		leased.emplace_back(std::move(memory));
	}
	for (size_t first_index = 0; first_index < leased_addresses.size(); first_index++)
	{
		EXPECT_TRUE(leased_addresses[first_index] != nullptr);
		for (size_t second_index = first_index + 1;
		     second_index < leased_addresses.size(); second_index++)
		{
			EXPECT_TRUE(leased_addresses[first_index] !=
			            leased_addresses[second_index]);
		}
	}
	snapshot = GetJitPageRecycleTestSnapshot();
	EXPECT_TRUE(snapshot.resident == 0);
	EXPECT_TRUE(snapshot.acquire_hits == slot_capacity);
	for (auto& memory: leased)
		memory->Reset();

	// Contending consumers must never receive the same lease. Hold every page
	// until all workers have published so address uniqueness is observable.
	ResetJitPageRecyclePoolForTest();
	constexpr size_t worker_count = 16;
	std::vector<std::unique_ptr<ExecutableCodeMemory>> concurrency_donors;
	concurrency_donors.reserve(worker_count);
	for (size_t index = 0; index < worker_count; index++)
	{
		auto memory = std::make_unique<ExecutableCodeMemory>();
		EXPECT_STATUS(memory->Allocate(first_buffer.SizeBytes()), Status::Ok);
		EXPECT_STATUS(memory->Publish(first_buffer.Data(), first_buffer.SizeBytes()),
		              Status::Ok);
		concurrency_donors.emplace_back(std::move(memory));
	}
	for (auto& memory: concurrency_donors)
		memory->RetireForReuseAfterQuiescenceForTest();
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == worker_count);

	std::array<const void*, worker_count> concurrent_addresses {};
	std::array<Status, worker_count> concurrent_allocate {};
	std::array<Status, worker_count> concurrent_publish {};
	std::array<uint64_t, worker_count> concurrent_results {};
	std::atomic<size_t> ready {0};
	std::atomic<bool> release {false};
	std::vector<std::thread> workers;
	workers.reserve(worker_count);
	for (size_t index = 0; index < worker_count; index++)
	{
		workers.emplace_back(
		    [&, index]()
		    {
			    ExecutableCodeMemory memory;
			    concurrent_allocate[index] =
			        memory.Allocate(second_buffer.SizeBytes());
			    if (concurrent_allocate[index] == Status::Ok)
			    {
				    concurrent_publish[index] = memory.Publish(
				        second_buffer.Data(), second_buffer.SizeBytes());
				    concurrent_addresses[index] = memory.EntryAddress();
			    } else
			    {
				    concurrent_publish[index] = Status::NotAllocated;
			    }
			    ready.fetch_add(1, std::memory_order_release);
			    while (!release.load(std::memory_order_acquire))
				    std::this_thread::yield();
			    const SmokeEntry entry = GetSmokeEntry(memory);
			    if (entry != nullptr) concurrent_results[index] = entry();
			    memory.Reset();
		    });
	}
	const auto deadline =
	    std::chrono::steady_clock::now() + std::chrono::seconds(2);
	while (ready.load(std::memory_order_acquire) != worker_count &&
	       std::chrono::steady_clock::now() < deadline)
	{
		std::this_thread::yield();
	}
	const bool all_ready = ready.load(std::memory_order_acquire) == worker_count;
	EXPECT_TRUE(all_ready);
	release.store(true, std::memory_order_release);
	for (auto& worker: workers)
		worker.join();
	for (size_t first_index = 0; first_index < worker_count; first_index++)
	{
		EXPECT_STATUS(concurrent_allocate[first_index], Status::Ok);
		EXPECT_STATUS(concurrent_publish[first_index], Status::Ok);
		EXPECT_TRUE(concurrent_addresses[first_index] != nullptr);
		EXPECT_TRUE(concurrent_results[first_index] == second_value);
		for (size_t second_index = first_index + 1;
		     second_index < worker_count; second_index++)
		{
			EXPECT_TRUE(concurrent_addresses[first_index] !=
			            concurrent_addresses[second_index]);
		}
	}
	EXPECT_TRUE(GetJitPageRecycleTestSnapshot().resident == 0);

#if defined(LUMEN_A64_DYNAREC_HOST_PC_PROFILE)
	// The tagged sidecar closes the old generation before the same base is
	// republished, so attribution cannot merge two physical-page leases.
	ResetJitPageRecyclePoolForTest();
	EXPECT_TRUE(ResetHostPcProfileForTest(4, true));
	SetHostPcProfileClockForTest(100);
	EXPECT_TRUE(PrepareHostPcProfile());
	ExecutableCodeMemory profiled_first;
	EXPECT_STATUS(profiled_first.Allocate(first_buffer.SizeBytes()), Status::Ok);
	EXPECT_STATUS(profiled_first.Publish(first_buffer.Data(), first_buffer.SizeBytes()),
	              Status::Ok);
	const auto profiled_base = reinterpret_cast<uintptr_t>(
	    profiled_first.EntryAddress());
	const uint64_t profiled_first_epoch = profiled_first.Epoch();
	EXPECT_TRUE(BeginHostPcProfile(200));
	SetHostPcProfileClockForTest(250);
	profiled_first.RetireForReuseAfterQuiescenceForTest();
	SetHostPcProfileClockForTest(300);
	ExecutableCodeMemory profiled_second;
	EXPECT_STATUS(profiled_second.Allocate(second_buffer.SizeBytes()), Status::Ok);
	EXPECT_STATUS(profiled_second.Publish(second_buffer.Data(), second_buffer.SizeBytes()),
	              Status::Ok);
	EXPECT_TRUE(reinterpret_cast<uintptr_t>(profiled_second.EntryAddress()) ==
	            profiled_base);
	EXPECT_TRUE(profiled_second.Epoch() != profiled_first_epoch);
	EXPECT_TRUE(ClaimCloseHostPcProfile(400));
	HostPcProfileSnapshot recycle_snapshot {};
	EXPECT_TRUE(FinishHostPcProfileSnapshot(&recycle_snapshot));
	const auto recycle_records = ReadAllHostPcRecords(recycle_snapshot);
	EXPECT_TRUE(recycle_records.size() == 2);
	if (recycle_records.size() == 2)
	{
		EXPECT_TRUE(recycle_records[0].base == profiled_base);
		EXPECT_TRUE(recycle_records[0].epoch == profiled_first_epoch);
		EXPECT_TRUE(recycle_records[0].publish_ns == 100);
		EXPECT_TRUE(recycle_records[0].retire_ns == 250);
		EXPECT_TRUE(recycle_records[1].base == profiled_base);
		EXPECT_TRUE(recycle_records[1].epoch == profiled_second.Epoch());
		EXPECT_TRUE(recycle_records[1].publish_ns == 300);
		EXPECT_TRUE(recycle_records[1].retire_ns == 0);
	}
	EXPECT_TRUE(recycle_snapshot.checksum ==
	            ReferenceHostPcChecksum(recycle_snapshot, recycle_records));
	profiled_second.Reset();
#endif
	ResetJitPageRecyclePoolForTest();
#endif
}
#endif

#if defined(LUMEN_VERIFIED_IR_BENCHMARK)
std::array<FastOp, 16> VerifiedIrBenchmarkFastOps()
{
	std::array<FastOp, 8> source {};
	source[0].kind   = FastOpKind::Nop;
	source[0].length = 1;
	source[1].kind   = FastOpKind::MovImmReg64;
	source[1].dst    = 0;
	source[1].target = 0x100;
	source[1].length = 10;
	source[2].kind   = FastOpKind::MovReg64;
	source[2].dst    = 0;
	source[2].src    = 1;
	source[2].length = 3;
	source[3].kind      = FastOpKind::AddReg64Imm;
	source[3].dst       = 1;
	source[3].immediate = 5;
	source[3].length    = 4;
	source[4].kind      = FastOpKind::SubReg32Imm;
	source[4].dst       = 2;
	source[4].immediate = 2;
	source[4].length    = 4;
	source[5].kind      = FastOpKind::CmpReg64Imm;
	source[5].dst       = 1;
	source[5].immediate = 0x105;
	source[5].length    = 4;
	source[6].kind      = FastOpKind::VmovPackedReg;
	source[6].dst       = 2;
	source[6].base      = 0;
	source[6].immediate = 2;
	source[6].condition =
	    IrVectorFlagMask(IrVectorFlag::ZeroUpper);
	source[6].length = 4;
	source[7].kind   = FastOpKind::VxorPackedReg;
	source[7].dst    = 3;
	source[7].src    = 2;
	source[7].base   = 1;
	source[7].immediate = 2;
	source[7].condition =
	    IrVectorFlagMask(IrVectorFlag::ZeroUpper);
	source[7].length = 4;

	std::array<FastOp, 16> operations {};
	uint64_t rip = 0x10000a000ULL;
	for (size_t index = 0; index < operations.size(); index++)
	{
		operations[index] = source[index % source.size()];
		operations[index].rip = rip;
		rip += operations[index].length;
	}
	return operations;
}

Status RunVerifiedIrBenchmarkIteration(
	bool candidate, const std::array<FastOp, 16>& operations,
	std::array<uint8_t, 4096>* storage, size_t* encoded_size,
	uint8_t* direct_instruction_count)
{
	constexpr EligibilityPolicy policy =
	    EligibilityPolicy::ExistingOrDirectBasicBlock;
	if (candidate)
	{
		auto verified = LowerFastOpsVerified(
		    operations.data(), operations.size());
		if (verified.status != Status::Ok) return verified.status;
		if (!verified.block.has_value()) return Status::InvalidIr;
		if (!Lumen::Cpu::A64Dynarec::IsRuntimeEligible(
		        *verified.block, policy))
		{
			return Status::UnsupportedOperation;
		}
		return EncodeVerifiedIrBlockForTest(
		    *verified.block, storage->data(), storage->size(), encoded_size,
		    direct_instruction_count, policy);
	}

	IrBlock block {};
	Status status = LowerFastOps(
	    operations.data(), operations.size(), &block);
	if (status != Status::Ok) return status;
	if (!Lumen::Cpu::A64Dynarec::IsRuntimeEligible(block, policy))
		return Status::UnsupportedOperation;
	return EncodeIrBlock(
	    block, storage->data(), storage->size(), encoded_size,
	    direct_instruction_count, policy);
}

uint64_t VerifiedIrBenchmarkChecksum(
	const std::array<uint8_t, 4096>& storage, size_t encoded_size)
{
	constexpr uint64_t offset_basis = 14695981039346656037ULL;
	constexpr uint64_t prime = 1099511628211ULL;
	uint64_t hash = offset_basis;
	for (size_t index = 0; index < encoded_size; index++)
	{
		hash ^= storage[index];
		hash *= prime;
	}
	return hash;
}

int RunVerifiedIrBenchmark()
{
	constexpr const char* selector_name =
	    "LUMEN_X64_A64_DYNAREC_VERIFIED_IR_PIPELINE";
	const char* selector = std::getenv(selector_name);
	if (selector == nullptr ||
	    (std::strcmp(selector, "0") != 0 && std::strcmp(selector, "1") != 0))
	{
		std::fprintf(stderr,
		             "VERIFIED_IR_BENCH requires %s=0 or %s=1\n",
		             selector_name, selector_name);
		return 2;
	}
	const bool candidate = std::strcmp(selector, "1") == 0;
	constexpr size_t warmup_iterations = 4096;
	constexpr size_t iterations = 200000;
	const auto operations = VerifiedIrBenchmarkFastOps();

	// Establish byte-for-byte equivalence outside the timed region. This also
	// keeps correctness failures distinct from the mechanical timing result.
	std::array<uint8_t, 4096> baseline_storage {};
	std::array<uint8_t, 4096> candidate_storage {};
	size_t baseline_size = 0;
	size_t candidate_size = 0;
	uint8_t baseline_direct_count = 0;
	uint8_t candidate_direct_count = 0;
	const Status baseline_status = RunVerifiedIrBenchmarkIteration(
	    false, operations, &baseline_storage, &baseline_size,
	    &baseline_direct_count);
	const Status candidate_status = RunVerifiedIrBenchmarkIteration(
	    true, operations, &candidate_storage, &candidate_size,
	    &candidate_direct_count);
	if (baseline_status != Status::Ok || candidate_status != Status::Ok ||
	    baseline_size != candidate_size ||
	    baseline_direct_count != candidate_direct_count ||
	    std::memcmp(baseline_storage.data(), candidate_storage.data(),
	                baseline_size) != 0)
	{
		std::fprintf(
		    stderr,
		    "VERIFIED_IR_BENCH equivalence_failed baseline_status=%s "
		    "candidate_status=%s baseline_bytes=%zu candidate_bytes=%zu "
		    "baseline_direct=%u candidate_direct=%u\n",
		    StatusName(baseline_status), StatusName(candidate_status),
		    baseline_size, candidate_size,
		    static_cast<unsigned>(baseline_direct_count),
		    static_cast<unsigned>(candidate_direct_count));
		return 3;
	}

	std::array<uint8_t, 4096> storage {};
	size_t encoded_size = 0;
	uint8_t direct_instruction_count = 0;
	for (size_t iteration = 0; iteration < warmup_iterations; iteration++)
	{
		const Status status = RunVerifiedIrBenchmarkIteration(
		    candidate, operations, &storage, &encoded_size,
		    &direct_instruction_count);
		if (status != Status::Ok)
		{
			std::fprintf(stderr,
			             "VERIFIED_IR_BENCH warmup_failed iteration=%zu status=%s\n",
			             iteration, StatusName(status));
			return 4;
		}
	}

	uint64_t total_encoded_bytes = 0;
	uint64_t total_direct_instructions = 0;
	Status status = Status::Ok;
	const auto begin = std::chrono::steady_clock::now();
	for (size_t iteration = 0; iteration < iterations; iteration++)
	{
		status = RunVerifiedIrBenchmarkIteration(
		    candidate, operations, &storage, &encoded_size,
		    &direct_instruction_count);
		if (status != Status::Ok) break;
		total_encoded_bytes += encoded_size;
		total_direct_instructions += direct_instruction_count;
	}
	const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
	    std::chrono::steady_clock::now() - begin);
	const uint64_t checksum = VerifiedIrBenchmarkChecksum(storage, encoded_size);
	const bool complete =
	    status == Status::Ok &&
	    total_encoded_bytes == static_cast<uint64_t>(encoded_size) * iterations &&
	    total_direct_instructions ==
	        static_cast<uint64_t>(direct_instruction_count) * iterations;

	std::printf(
	    "VERIFIED_IR_BENCH variant=%s iterations=%zu operations=%zu "
	    "elapsed_ns=%lld status=%s encoded_bytes=%zu total_encoded_bytes=%llu "
	    "direct_instructions=%u validations=%llu full=%llu structure=%llu "
	    "checksum=%016llx\n",
	    candidate ? "candidate" : "baseline", iterations, operations.size(),
	    static_cast<long long>(elapsed.count()), StatusName(status), encoded_size,
	    static_cast<unsigned long long>(total_encoded_bytes),
	    static_cast<unsigned>(direct_instruction_count),
	    static_cast<unsigned long long>(0),
	    static_cast<unsigned long long>(0),
	    static_cast<unsigned long long>(0),
	    static_cast<unsigned long long>(checksum));
	return complete ? 0 : 5;
}
#endif

