bool IrValidatorBenchmarkInstructionsEqual(
	const IrInstruction& lhs, const IrInstruction& rhs)
{
	return lhs.opcode == rhs.opcode && lhs.width == rhs.width &&
	       lhs.destination == rhs.destination && lhs.source == rhs.source &&
	       lhs.source_width == rhs.source_width && lhs.source2 == rhs.source2 &&
	       lhs.condition == rhs.condition &&
	       lhs.vector_flags == rhs.vector_flags && lhs.length == rhs.length &&
	       lhs.step_cost == rhs.step_cost && lhs.effects == rhs.effects &&
	       lhs.address.base == rhs.address.base &&
	       lhs.address.index == rhs.address.index &&
	       lhs.address.scale == rhs.address.scale &&
	       lhs.address.displacement == rhs.address.displacement &&
	       lhs.address.absolute == rhs.address.absolute && lhs.rip == rhs.rip &&
	       lhs.immediate == rhs.immediate && lhs.target == rhs.target;
}

bool IrValidatorBenchmarkBlocksEqual(const IrBlock& lhs, const IrBlock& rhs)
{
	if (lhs.rip != rhs.rip || lhs.fallthrough_rip != rhs.fallthrough_rip ||
	    lhs.semantic_mask != rhs.semantic_mask ||
	    lhs.instruction_count != rhs.instruction_count ||
	    lhs.has_terminator != rhs.has_terminator)
	{
		return false;
	}
	for (size_t index = 0; index < lhs.instruction_count; index++)
	{
		if (!IrValidatorBenchmarkInstructionsEqual(
		        lhs.instructions[index], rhs.instructions[index]))
		{
			return false;
		}
	}
	return true;
}

uint64_t IrValidatorBenchmarkHashValue(uint64_t hash, uint64_t value)
{
	constexpr uint64_t prime = 1099511628211ULL;
	for (unsigned byte = 0; byte < 8; byte++)
	{
		hash ^= static_cast<uint8_t>(value >> (byte * 8u));
		hash *= prime;
	}
	return hash;
}

uint64_t IrValidatorBenchmarkChecksum(const IrBlock& block)
{
	uint64_t hash = 14695981039346656037ULL;
	hash = IrValidatorBenchmarkHashValue(hash, block.rip);
	hash = IrValidatorBenchmarkHashValue(hash, block.fallthrough_rip);
	hash = IrValidatorBenchmarkHashValue(hash, block.semantic_mask);
	hash = IrValidatorBenchmarkHashValue(hash, block.instruction_count);
	hash = IrValidatorBenchmarkHashValue(hash, block.has_terminator ? 1 : 0);
	for (size_t index = 0; index < block.instruction_count; index++)
	{
		const IrInstruction& instruction = block.instructions[index];
		hash = IrValidatorBenchmarkHashValue(
		    hash, static_cast<uint8_t>(instruction.opcode));
		hash = IrValidatorBenchmarkHashValue(hash, instruction.width);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.destination);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.source);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.source_width);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.source2);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.condition);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.vector_flags);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.length);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.step_cost);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.effects);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.address.base);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.address.index);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.address.scale);
		hash = IrValidatorBenchmarkHashValue(
		    hash, static_cast<uint32_t>(instruction.address.displacement));
		hash = IrValidatorBenchmarkHashValue(hash, instruction.address.absolute);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.rip);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.immediate);
		hash = IrValidatorBenchmarkHashValue(hash, instruction.target);
	}
	return hash;
}

int RunIrValidatorBenchmark()
{
	constexpr const char* selector_name =
	    "LUMEN_X64_A64_DYNAREC_BRANCH_LOCAL_IR_VALIDATION";
	const char* selector = std::getenv(selector_name);
	if (selector == nullptr ||
	    (std::strcmp(selector, "0") != 0 && std::strcmp(selector, "1") != 0))
	{
		std::fprintf(stderr,
		             "IR_VALIDATOR_BENCH requires %s=0 or %s=1\n",
		             selector_name, selector_name);
		return 2;
	}
	const bool branch_local = std::strcmp(selector, "1") == 0;
	constexpr size_t direct_warmup_iterations = 16384;
	constexpr size_t direct_iterations = 4000000;
	constexpr size_t lower_warmup_iterations = 4096;
	constexpr size_t lower_iterations = 1000000;
	const auto operations = IrValidatorBenchmarkFastOps();

	IrBlock reference_block {};
	const Status reference_status = LowerFastOps(
	    operations.data(), operations.size(), &reference_block);
	auto selected_block = LowerFastOpsVerified(
	    operations.data(), operations.size());
	if (reference_status != Status::Ok || selected_block.status != Status::Ok ||
	    !selected_block.block.has_value() ||
	    !IrValidatorBenchmarkBlocksEqual(
	        reference_block, selected_block.block->Block()))
	{
		std::fprintf(
		    stderr,
		    "IR_VALIDATOR_BENCH equivalence_failed reference_status=%s "
		    "selected_status=%s selected_block=%u\n",
		    StatusName(reference_status), StatusName(selected_block.status),
		    selected_block.block.has_value() ? 1u : 0u);
		return 3;
	}

	for (size_t index = 0; index < reference_block.instruction_count; index++)
	{
		const IrInstruction& instruction = reference_block.instructions[index];
		const bool eager = ValidateIrInstructionForBenchmark(instruction, false);
		const bool local = ValidateIrInstructionForBenchmark(instruction, true);
		if (!eager || !local || eager != local)
		{
			std::fprintf(stderr,
			             "IR_VALIDATOR_BENCH validator_equivalence_failed "
			             "instruction=%zu eager=%u branch_local=%u\n",
			             index, eager ? 1u : 0u, local ? 1u : 0u);
			return 4;
		}
	}

	uint64_t warmup_observation = 0;
	for (size_t iteration = 0; iteration < direct_warmup_iterations; iteration++)
	{
		for (size_t index = 0; index < reference_block.instruction_count; index++)
		{
			warmup_observation += ValidateIrInstructionForBenchmark(
			    reference_block.instructions[index], branch_local) ? 1u : 0u;
		}
	}
	for (size_t iteration = 0; iteration < lower_warmup_iterations; iteration++)
	{
		auto verified = LowerFastOpsVerified(
		    operations.data(), operations.size());
		if (verified.status != Status::Ok || !verified.block.has_value())
		{
			std::fprintf(stderr,
			             "IR_VALIDATOR_BENCH lower_warmup_failed "
			             "iteration=%zu status=%s\n",
			             iteration, StatusName(verified.status));
			return 5;
		}
		warmup_observation += verified.block->Block().instruction_count;
	}

	uint64_t direct_true_count = 0;
	const auto direct_begin = std::chrono::steady_clock::now();
	for (size_t iteration = 0; iteration < direct_iterations; iteration++)
	{
		for (size_t index = 0; index < reference_block.instruction_count; index++)
		{
			direct_true_count += ValidateIrInstructionForBenchmark(
			    reference_block.instructions[index], branch_local) ? 1u : 0u;
		}
	}
	const auto direct_elapsed =
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - direct_begin);

	Status lower_status = Status::Ok;
	uint64_t lower_block_count = 0;
	uint64_t lower_instruction_count = 0;
	uint64_t lower_observation = 0;
	const auto lower_begin = std::chrono::steady_clock::now();
	for (size_t iteration = 0; iteration < lower_iterations; iteration++)
	{
		auto verified = LowerFastOpsVerified(
		    operations.data(), operations.size());
		lower_status = verified.status;
		if (lower_status != Status::Ok || !verified.block.has_value())
		{
			if (lower_status == Status::Ok) lower_status = Status::InvalidIr;
			break;
		}
		const IrBlock& block = verified.block->Block();
		lower_block_count++;
		lower_instruction_count += block.instruction_count;
		lower_observation += block.rip ^ block.fallthrough_rip ^
		                     block.semantic_mask ^ block.instruction_count;
	}
	const auto lower_elapsed =
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - lower_begin);

	const uint64_t expected_direct_count =
	    static_cast<uint64_t>(direct_iterations) *
	    reference_block.instruction_count;
	const uint64_t expected_lower_instruction_count =
	    static_cast<uint64_t>(lower_iterations) *
	    reference_block.instruction_count;
	const bool direct_complete = direct_true_count == expected_direct_count;
	const bool lower_complete = lower_status == Status::Ok &&
	                            lower_block_count == lower_iterations &&
	                            lower_instruction_count ==
	                                expected_lower_instruction_count;
	const uint64_t block_checksum =
	    IrValidatorBenchmarkChecksum(reference_block);
	uint64_t direct_checksum = IrValidatorBenchmarkHashValue(
	    block_checksum, direct_true_count);
	direct_checksum = IrValidatorBenchmarkHashValue(
	    direct_checksum, expected_direct_count);
	uint64_t lower_checksum = IrValidatorBenchmarkHashValue(
	    block_checksum, lower_observation);
	lower_checksum = IrValidatorBenchmarkHashValue(
	    lower_checksum, lower_instruction_count);

	std::printf(
	    "IR_VALIDATOR_BENCH variant=%s operations=%zu "
	    "direct_iterations=%zu direct_elapsed_ns=%lld direct_calls=%llu "
	    "direct_true=%llu direct_status=%s direct_checksum=%016llx "
	    "lower_iterations=%zu lower_elapsed_ns=%lld lower_blocks=%llu "
	    "lower_instructions=%llu lower_status=%s lower_checksum=%016llx "
	    "warmup_observation=%llu\n",
	    branch_local ? "branch-local" : "eager", operations.size(),
	    direct_iterations, static_cast<long long>(direct_elapsed.count()),
	    static_cast<unsigned long long>(expected_direct_count),
	    static_cast<unsigned long long>(direct_true_count),
	    direct_complete ? "Ok" : "InvalidIr",
	    static_cast<unsigned long long>(direct_checksum), lower_iterations,
	    static_cast<long long>(lower_elapsed.count()),
	    static_cast<unsigned long long>(lower_block_count),
	    static_cast<unsigned long long>(lower_instruction_count),
	    StatusName(lower_status),
	    static_cast<unsigned long long>(lower_checksum),
	    static_cast<unsigned long long>(warmup_observation));
	return direct_complete && lower_complete ? 0 : 6;
}
#endif

#if defined(LUMEN_JIT_PAGE_RECYCLE_BENCHMARK)
int RunJitPageRecycleBenchmark()
{
	if (!LUMEN_A64_TEST_HAS_MACOS_JIT_CALLBACK || !IsHostSupported())
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH unavailable\n");
		return 2;
	}
	const char* selector = std::getenv(
	    "LUMEN_X64_A64_DYNAREC_JIT_PAGE_RECYCLE");
	if (selector == nullptr ||
	    (std::strcmp(selector, "0") != 0 && std::strcmp(selector, "1") != 0))
	{
		std::fprintf(
		    stderr,
		    "JIT_PAGE_RECYCLE_BENCH requires "
		    "LUMEN_X64_A64_DYNAREC_JIT_PAGE_RECYCLE=0 or 1\n");
		return 2;
	}
	const bool candidate = std::strcmp(selector, "1") == 0;
	if (IsJitPageRecycleEnabled() != candidate)
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH selector_mismatch\n");
		return 3;
	}

	constexpr std::array<uint64_t, 2> values = {
	    0x123456789abcdef0ULL,
	    0xfedcba9876543210ULL,
	};
	std::array<uint8_t, 24> first_staging {};
	std::array<uint8_t, 24> second_staging {};
	A64CodeBuffer first_buffer(first_staging.data(), first_staging.size());
	A64CodeBuffer second_buffer(second_staging.data(), second_staging.size());
	if (first_buffer.EmitReturnConstant(values[0]) != Status::Ok ||
	    second_buffer.EmitReturnConstant(values[1]) != Status::Ok)
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH encode_failed\n");
		return 4;
	}
	const std::array<const A64CodeBuffer*, 2> buffers = {
	    &first_buffer,
	    &second_buffer,
	};

	// Existing published-code execution is the negative-control hot path. The
	// selector and recycler must add no work here.
	ResetJitPageRecyclePoolForTest();
	ExecutableCodeMemory hot_memory;
	if (hot_memory.Allocate(first_buffer.SizeBytes()) != Status::Ok ||
	    hot_memory.Publish(first_buffer.Data(), first_buffer.SizeBytes()) !=
	        Status::Ok)
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH hot_publish_failed\n");
		return 5;
	}
	const SmokeEntry hot_entry = GetSmokeEntry(hot_memory);
	if (hot_entry == nullptr)
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH hot_entry_missing\n");
		return 5;
	}
	constexpr size_t hot_warmup_iterations = 65536;
	constexpr size_t hot_iterations = 1000000000;
	uint64_t hot_warmup_checksum = 0;
	for (size_t iteration = 0; iteration < hot_warmup_iterations; iteration++)
		hot_warmup_checksum += hot_entry();
	uint64_t hot_checksum = 0;
	const auto hot_begin = std::chrono::steady_clock::now();
	for (size_t iteration = 0; iteration < hot_iterations; iteration++)
		hot_checksum += hot_entry();
	const auto hot_elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
	    std::chrono::steady_clock::now() - hot_begin);
	hot_memory.Reset();
	if (hot_warmup_checksum !=
	        values[0] * static_cast<uint64_t>(hot_warmup_iterations) ||
	    hot_checksum != values[0] * static_cast<uint64_t>(hot_iterations))
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH hot_checksum_failed\n");
		return 6;
	}

	// Exercise the exact allocate/publish/execute/quiescent-retire lifecycle.
	auto churn = [&](size_t iterations, uint64_t* checksum) -> uint32_t
	{
		uint32_t failures = 0;
		uint64_t sum = 0;
		for (size_t iteration = 0; iteration < iterations; iteration++)
		{
			const size_t value_index = iteration & 1u;
			const A64CodeBuffer& buffer = *buffers[value_index];
			ExecutableCodeMemory memory;
			if (memory.Allocate(buffer.SizeBytes()) != Status::Ok ||
			    memory.Publish(buffer.Data(), buffer.SizeBytes()) != Status::Ok)
			{
				failures++;
				continue;
			}
			const SmokeEntry entry = GetSmokeEntry(memory);
			if (entry == nullptr)
			{
				failures++;
			} else
			{
				const uint64_t result = entry();
				if (result != values[value_index]) failures++;
				sum += result;
			}
			memory.RetireForReuseAfterQuiescenceForTest();
		}
		*checksum = sum;
		return failures;
	};

	constexpr size_t churn_warmup_iterations = 256;
	uint64_t churn_warmup_checksum = 0;
	if (churn(churn_warmup_iterations, &churn_warmup_checksum) != 0)
	{
		std::fprintf(stderr, "JIT_PAGE_RECYCLE_BENCH churn_warmup_failed\n");
		return 7;
	}
	ResetJitPageRecyclePoolForTest();
	constexpr size_t churn_iterations = 20000;
	uint64_t churn_checksum = 0;
	const auto churn_begin = std::chrono::steady_clock::now();
	const uint32_t churn_failures = churn(churn_iterations, &churn_checksum);
	const auto churn_elapsed =
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - churn_begin);
	const auto churn_snapshot = GetJitPageRecycleTestSnapshot();

	uint64_t expected_churn_checksum = 0;
	for (size_t iteration = 0; iteration < churn_iterations; iteration++)
		expected_churn_checksum += values[iteration & 1u];
	if (churn_failures != 0 || churn_checksum != expected_churn_checksum ||
	    (candidate &&
	     (churn_snapshot.acquire_hits < churn_iterations - 1 ||
	      churn_snapshot.resident != 1 ||
	      churn_snapshot.retire_stored != churn_iterations)) ||
	    (!candidate &&
	     (churn_snapshot.acquire_hits != 0 || churn_snapshot.resident != 0 ||
	      churn_snapshot.retire_stored != 0)))
	{
		std::fprintf(stderr,
		             "JIT_PAGE_RECYCLE_BENCH churn_verification_failed\n");
		return 8;
	}

	// Separate multiwriter timing catches global-pool contention. Each mapping
	// stays thread-owned until retirement; the shared state is only the pool.
	ResetJitPageRecyclePoolForTest();
	constexpr size_t writer_count = 8;
	constexpr size_t iterations_per_writer = 2000;
	std::atomic<size_t> ready {0};
	std::atomic<bool> start {false};
	std::atomic<uint32_t> multiwriter_failures {0};
	std::atomic<uint64_t> multiwriter_checksum {0};
	std::vector<std::thread> workers;
	workers.reserve(writer_count);
	for (size_t writer = 0; writer < writer_count; writer++)
	{
		workers.emplace_back(
		    [&, writer]()
		    {
			    ready.fetch_add(1, std::memory_order_release);
			    while (!start.load(std::memory_order_acquire))
				    std::this_thread::yield();
			    uint64_t local_checksum = 0;
			    uint32_t local_failures = 0;
			    for (size_t iteration = 0;
			         iteration < iterations_per_writer; iteration++)
			    {
				    const size_t value_index = (writer + iteration) & 1u;
				    const A64CodeBuffer& buffer = *buffers[value_index];
				    ExecutableCodeMemory memory;
				    if (memory.Allocate(buffer.SizeBytes()) != Status::Ok ||
				        memory.Publish(buffer.Data(), buffer.SizeBytes()) !=
				            Status::Ok)
				    {
					    local_failures++;
					    continue;
				    }
				    const SmokeEntry entry = GetSmokeEntry(memory);
				    if (entry == nullptr)
				    {
					    local_failures++;
				    } else
				    {
					    const uint64_t result = entry();
					    if (result != values[value_index]) local_failures++;
					    local_checksum += result;
				    }
				    memory.RetireForReuseAfterQuiescenceForTest();
			    }
			    multiwriter_failures.fetch_add(
			        local_failures, std::memory_order_relaxed);
			    multiwriter_checksum.fetch_add(
			        local_checksum, std::memory_order_relaxed);
		    });
	}
	while (ready.load(std::memory_order_acquire) != writer_count)
		std::this_thread::yield();
	const auto multiwriter_begin = std::chrono::steady_clock::now();
	start.store(true, std::memory_order_release);
	for (auto& worker: workers)
		worker.join();
	const auto multiwriter_elapsed =
	    std::chrono::duration_cast<std::chrono::nanoseconds>(
	        std::chrono::steady_clock::now() - multiwriter_begin);
	const auto multiwriter_snapshot = GetJitPageRecycleTestSnapshot();

	uint64_t expected_multiwriter_checksum = 0;
	for (size_t writer = 0; writer < writer_count; writer++)
	{
		for (size_t iteration = 0; iteration < iterations_per_writer;
		     iteration++)
		{
			expected_multiwriter_checksum += values[(writer + iteration) & 1u];
		}
	}
	const bool multiwriter_valid =
	    multiwriter_failures.load(std::memory_order_relaxed) == 0 &&
	    multiwriter_checksum.load(std::memory_order_relaxed) ==
	        expected_multiwriter_checksum &&
	    (!candidate ||
	     (multiwriter_snapshot.acquire_hits >=
	          writer_count * iterations_per_writer - writer_count &&
	      multiwriter_snapshot.resident <= writer_count)) &&
	    (candidate ||
	     (multiwriter_snapshot.acquire_hits == 0 &&
	      multiwriter_snapshot.resident == 0));
	if (!multiwriter_valid)
	{
		std::fprintf(stderr,
		             "JIT_PAGE_RECYCLE_BENCH multiwriter_verification_failed\n");
		return 9;
	}

	std::printf(
	    "JIT_PAGE_RECYCLE_BENCH variant=%s build=Release host=macos-arm64 "
	    "hot_iterations=%zu hot_elapsed_ns=%lld hot_checksum=%016llx "
	    "churn_iterations=%zu churn_elapsed_ns=%lld "
	    "churn_acquire_hits=%llu churn_retire_stored=%llu "
	    "writers=%zu iterations_per_writer=%zu multiwriter_elapsed_ns=%lld "
	    "multiwriter_acquire_hits=%llu multiwriter_resident=%zu "
	    "checksum=%016llx failures=0\n",
	    candidate ? "candidate" : "baseline", hot_iterations,
	    static_cast<long long>(hot_elapsed.count()),
	    static_cast<unsigned long long>(hot_checksum), churn_iterations,
	    static_cast<long long>(churn_elapsed.count()),
	    static_cast<unsigned long long>(churn_snapshot.acquire_hits),
	    static_cast<unsigned long long>(churn_snapshot.retire_stored),
	    writer_count, iterations_per_writer,
	    static_cast<long long>(multiwriter_elapsed.count()),
	    static_cast<unsigned long long>(multiwriter_snapshot.acquire_hits),
	    multiwriter_snapshot.resident,
	    static_cast<unsigned long long>(churn_checksum));
	ResetJitPageRecyclePoolForTest();
	return 0;
}
#endif

#if defined(LUMEN_JIT_PUBLICATION_BENCHMARK)
int RunJitPublicationBenchmark()
{
	if (!LUMEN_A64_TEST_HAS_MACOS_JIT_CALLBACK || !IsHostSupported())
	{
		std::fprintf(stderr, "JIT_PUBLICATION_BENCH unavailable\n");
		return 2;
	}

	constexpr size_t writer_count = 16;
	constexpr size_t mappings_per_writer = 128;
	constexpr size_t publication_size = 16384;
	constexpr size_t mapping_count = writer_count * mappings_per_writer;
	std::array<uint8_t, publication_size> staging {};
	for (size_t index = 0; index < staging.size(); index++)
	{
		staging[index] = static_cast<uint8_t>((index % 251) + 1);
	}
	std::vector<std::unique_ptr<ExecutableCodeMemory>> mappings;
	mappings.reserve(mapping_count);
	for (size_t index = 0; index < mapping_count; index++)
	{
		auto mapping = std::make_unique<ExecutableCodeMemory>();
		const Status status = mapping->Allocate(publication_size);
		if (status != Status::Ok)
		{
			std::fprintf(stderr, "JIT_PUBLICATION_BENCH allocation_failed index=%zu status=%s\n",
			             index, StatusName(status));
			return 3;
		}
		mappings.emplace_back(std::move(mapping));
	}

	std::atomic<uint32_t> ready {0};
	std::atomic<bool> start {false};
	std::atomic<uint32_t> failures {0};
	std::vector<std::thread> workers;
	workers.reserve(writer_count);
	for (size_t writer = 0; writer < writer_count; writer++)
	{
		workers.emplace_back(
		    [&, writer]()
		    {
			    ready.fetch_add(1, std::memory_order_release);
			    while (!start.load(std::memory_order_acquire))
			    {
			    }
			    const size_t begin = writer * mappings_per_writer;
			    const size_t end = begin + mappings_per_writer;
			    for (size_t index = begin; index < end; index++)
			    {
				    if (mappings[index]->Publish(staging.data(), staging.size()) != Status::Ok)
				    {
					    failures.fetch_add(1, std::memory_order_relaxed);
				    }
			    }
		    });
	}
	while (ready.load(std::memory_order_acquire) != writer_count)
	{
		std::this_thread::yield();
	}
	const auto begin = std::chrono::steady_clock::now();
	start.store(true, std::memory_order_release);
	for (auto& worker: workers)
		worker.join();
	const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
	    std::chrono::steady_clock::now() - begin);
	const uint32_t failed = failures.load(std::memory_order_relaxed);
	uint32_t verification_failures = 0;
	for (const auto& mapping: mappings)
	{
		const void* entry = mapping->EntryAddress();
		if (mapping->PublishedSize() != publication_size || entry == nullptr ||
		    std::memcmp(entry, staging.data(), staging.size()) != 0)
		{
			verification_failures++;
		}
	}
#if defined(LUMEN_JIT_COPY_LEGACY_REGISTRY_BENCHMARK)
	constexpr const char* variant = "baseline-global-lock";
#else
	constexpr const char* variant = "candidate-per-slot";
#endif
#if defined(NDEBUG)
	constexpr const char* build = "Release";
#else
	constexpr const char* build = "non-Release";
#endif
	std::printf("JIT_PUBLICATION_BENCH variant=%s build=%s host=macos-arm64 "
	            "writers=%zu mappings_per_writer=%zu bytes=%zu elapsed_ns=%lld "
	            "failures=%u verification_failures=%u\n",
	            variant, build, writer_count, mappings_per_writer, publication_size,
	            static_cast<long long>(elapsed.count()), failed, verification_failures);
	return failed == 0 && verification_failures == 0 ? 0 : 4;
}
#endif

